<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$counts=['products'=>(int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(),'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'new'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE status='new'")->fetchColumn(),'categories'=>(int)db()->query('SELECT COUNT(*) FROM categories')->fetchColumn()];$orders=db()->query('SELECT id,order_number,customer_name,phone,total,status,created_at FROM orders ORDER BY id DESC LIMIT 30')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة تحكم الفخامة</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><div class="adminbar"><b>الفخامة | لوحة الإدارة</b><span>مرحباً <?=h($_SESSION['admin_name'])?></span><a href="logout.php">تسجيل الخروج</a></div><main class="inner"><div class="adminnav"><a class="gold" href="products.php">إدارة المنتجات</a><a class="gold" href="categories.php">الأقسام</a><a class="gold" href="banners.php">البانرات</a></div><div class="stats"><div>المنتجات <b><?=$counts['products']?></b></div><div>الطلبات <b><?=$counts['orders']?></b></div><div>طلبات جديدة <b><?=$counts['new']?></b></div><div>الأقسام <b><?=$counts['categories']?></b></div></div><h2>أحدث الطلبات</h2><div class="table-wrap"><table><tr><th>رقم الطلب</th><th>العميل</th><th>الهاتف</th><th>الإجمالي</th><th>الحالة</th><th>التاريخ</th><th></th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['order_number'])?></td><td><?=h($o['customer_name'])?></td><td><?=h($o['phone'])?></td><td><?=money($o['total'])?></td><td><?=h($o['status'])?></td><td><?=h($o['created_at'])?></td><td><a href="order.php?id=<?=$o['id']?>">عرض</a></td></tr><?php endforeach?></table></div></main></body></html>